mapper.select:
SELECT ,
       tu.real_name AS teacherName,
       su.real_name AS studentName
FROM volunteer_record vr
LEFT JOIN user tu ON vr.teacher_id = tu.id
LEFT JOIN user su ON vr.student_id = su.id
LEFT JOIN teacher_profile t ON vr.teacher_id = t.user_id
LEFT JOIN student_profile s ON vr.student_id = s.user_id


        AND vr.teacher_id = #{teacherId}


        AND vr.student_id = #{studentId}


        AND vr.status = #{status}


        AND s.school_id = #{schoolId}


ORDER BY vr.create_time DESC
